// Reproduce: spyOn fails to mock inherited methods (deeply inherited)
import { spyOn } from '../src/index.ts'

class GrandParent {
  get inheritedGetter() { return 'grandparent'; }
  inheritedMethod() { return 'grandparent method'; }
}

class Parent extends GrandParent {
  // inherits everything from GrandParent
}

class Child extends Parent {
  // inherits everything from GrandParent via Parent
}

const child = new Child();

// This should work for inherited getter from deeply inherited prototype
try {
  const s = spyOn(child, { getter: 'inheritedGetter' }, () => 'mocked');
  console.log('Getter spy result:', child.inheritedGetter);
  s.restore();
