edits.newText:
let reassign = (cb: any) => {
  let { value, ...desc } = originalDescriptor || {
    configurable: true,
    writable: true,
  }
  if (accessType !== 'value') {
    delete desc.writable // getter/setter can't have writable attribute at all
  }
  ;(desc as PropertyDescriptor)[accessType] = cb
  define(obj, accessName, desc)
}
let restore = () => {
  if (originalDescriptor && !original) {
    define(obj, accessName, originalDescriptor)
  } else if (!isOwnDescriptor && objDescriptor === undefined) {
    // The original was inherited (not on obj itself), so delete the own property
    // we created during spying to let the prototype chain work again
    delete (obj as any)[accessName]
  } else {
    reassign(original)
  }
}

